package com.example.repository;

import com.example.dto.UserSummaryDto;
import com.example.model.User;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.util.List;

@Repository
public interface UserRepository extends JpaRepository<User, Long> {

    @Query(value = "SELECT id, username, email FROM users WHERE status = :status", nativeQuery = true)
    List<UserSummaryDto> findActiveUserSummaries(@Param("status") String status);

    @Modifying
    @Query(value = "UPDATE users SET status = 'INACTIVE' WHERE last_login < NOW() - INTERVAL '1 year'", nativeQuery = true)
    int deactivateStaleUsers();
}
